// 先把 DataA 的所有 json 取出來，放到一個陣列
const dataA = $input.all().map(item => item.json);

// DataB 的 items
const itemsB = $('inferences to the paragraph').first().json;

// 把 dataA 整個塞到 B 的 search 欄位
itemsB.search = dataA;

return itemsB;

const items = $input.all();

for (let i = 0; i < items.length; i++) {
  const old = items[i].json;
  // 先把 id 放在最前面，後面再展開原本的欄位
  items[i].json = { id: i + 1, ...old };
}

return items;

return items[0].json.items.slice(0, 5).map(r => ({
  title: r.title,
  link: r.link,
  snippet: r.snippet,
})).map(item => ({ json: item }));
